INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào thầy/cô, em muốn chọn lớp tiếng Trung nhưng nó đã hiện đầy chỗ rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp này hot nên chỗ đã bị đăng ký hết rồi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể chuyển sang lớp ở khung giờ khác được không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học giống hệt nhau.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em đổi trực tiếp sang lớp này được luôn phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em thao tác trực tiếp trên hệ thống là được, không cần xin phép thêm gì cả.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, rất vui được làm học trò của cô ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường, em đã quen với cuộc sống ở đây chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang quen dần ạ, em muốn hỏi cô một chút, việc chọn môn của chuyên ngành mình nên chú trọng điểm gì ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì có thể chọn những môn liên quan đến thương mại quốc tế nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Vâng ạ, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải thôi, không cần chọn quá nhiều môn, tránh áp lực quá lớn nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã hướng dẫn!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Bạn ơi, qua đây chụp ảnh làm thẻ sinh viên nào.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Vâng ạ, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em chưa rõ lắm.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản thôi, không đội mũ, không đeo kính râm, để lộ trán ra là được nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Vâng, để em chỉnh lại chút, thế này được chưa ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Cứ giữ nụ cười, nhìn vào ống kính, xong ngay thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là làm thẻ sinh viên luôn được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng vậy, ảnh sẽ nhập vào hệ thống, một tuần sau là em lấy thẻ được rồi.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào thầy/cô, em là sinh viên mới, muốn làm thẻ thư viện để mượn sách ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em xuất trình thẻ sinh viên là làm miễn phí cho em ngay nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Đây ạ, làm xong thì mỗi lần em được mượn mấy quyển sách vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Du học sinh mỗi lần được mượn mười quyển, thời hạn mượn là ba mươi ngày nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Trung này được chứ ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để cô quét mã đăng ký cho em, mượn thành công rồi đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh Vũ ơi, em không đăng nhập được email trường, mật khẩu ban đầu nó cứ báo sai.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy hả? Hay em gõ nhầm chữ hoa chữ thường rồi?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Cũng có thể lắm! Em toàn không để ý phân biệt hoa thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, anh chỉ cho, gõ lại đúng hoa thường là đăng nhập được ngay ấy mà.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Vào được rồi! Giờ muốn đổi mật khẩu thì làm sao ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào phần trung tâm cá nhân mà đặt mật khẩu mới, nhớ đặt phức tạp một chút nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Dạ được, em đổi ngay đây, cảm ơn anh nhiều lắm luôn!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào trợ giảng, em nộp bài trên hệ thống học tập mà cứ bị lỗi mãi không nộp được ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là không tải file lên được, hay là trang bị đơ vậy em?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ tải mãi không xong, em bấm nộp bài thì chẳng thấy phản hồi gì cả.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do hệ thống bị nghẽn vào buổi tối, hôm nay nhiều bạn cũng gặp tình trạng này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị tính trễ hạn rồi trừ điểm không ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, lỗi hệ thống thì sẽ gia hạn nộp bài cho tất cả, mai sáng nộp lại cũng được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','Tuyệt quá, cảm ơn thầy/cô đã báo cho em biết!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào cán bộ, em muốn hỏi về phạm vi chi trả của bảo hiểm y tế sinh viên quốc tế ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Không vấn đề gì, bảo hiểm của trường chủ yếu chi trả chi phí khám ngoại trú và nội trú ở bệnh viện công nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh vặt như cảm cúm, viêm dạ dày ruột cũng được chi trả đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được chứ, các bệnh thông thường đều nằm trong phạm vi chi trả, kể cả tai nạn thương tích cũng được bồi thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Cho em hỏi có những khoản nào không được chi trả không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, thẩm mỹ, làm trắng răng thì không được chi trả đâu nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn cán bộ đã giải thích tận tình!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào chị, em là sinh viên mới, đến khám sức khỏe nhập học, cho em hỏi thủ tục làm thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Em lấy số khám ở máy tự động trước, rồi điền vào tờ thông tin cá nhân này nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Dạ vâng, phần quốc tịch với loại giấy tờ trong tờ khai cứ điền đúng thực tế là được đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng rồi, thông tin phải điền chính xác hết, tránh để phiếu khám bị sai sót nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền xong tờ khai và lấy số rồi, tiếp theo làm gì ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Cầm phiếu đi khám lần lượt từng mục là được, quy trình đơn giản lắm nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi, cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','早高峰城市主干道普遍拥堵，乘客可礼貌请求司机绕路，司机一般会主动配合，不会额外加价；支路人流密集，司机通常会减速慢行保障安全。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','司机',1,'小伙子，跟你说一下，前方主干道早高峰全线拥堵，车速特别慢哦。','xiǎo huǒ zi， gēn nǐ shuō yī xià， qián fāng zhǔ gàn dào zǎo gāo fēng quán xiàn yōng dǔ， chē sù tè bié màn ó。','Cậu em ơi, nói cho biết trước, đường lớn phía trước giờ cao điểm sáng đang tắc kín hết, xe chạy chậm lắm đó.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','阮明',2,'师傅，我上午有专业课，还有十分钟就要上课，再堵下去肯定要迟到了呢！','shī fù， wǒ shàng wǔ yǒu zhuān yè kè， hái yǒu shí fēn zhōng jiù yào shàng kè， zài dǔ xià qù kěn dìng yào chí dào le ne！','Bác tài ơi, sáng nay em có tiết chuyên ngành, còn mười phút nữa là vào học rồi, cứ tắc thế này chắc trễ học mất!','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','司机',3,'我打开导航看看路况，主干道三条车道全部堵死，短时间疏通不开。','wǒ dǎ kāi dǎo háng kàn kàn lù kuàng， zhǔ gàn dào sān tiáo chē dào quán bù dǔ sǐ， duǎn shí jiān shū tōng bù kāi。','Để tôi mở bản đồ xem tình hình, cả ba làn đường lớn đều tắc cứng, khó mà thông nhanh được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','阮明',4,'那有没有别的小路可以绕一下，只要能赶在上课前到学校就行呀？','nà yǒu méi yǒu bié de xiǎo lù kě yǐ rào yī xià， zhǐ yào néng gǎn zài shàng kè qián dào xué xiào jiù xíng ya？','Vậy có đường nhỏ nào đi vòng được không ạ, miễn kịp giờ vào học là được rồi?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','司机',5,'倒是有一条居民区小路能绕行，唯一问题是路程会多两公里，稍微远一点。','dǎo shì yǒu yī tiáo jū mín qū xiǎo lù néng rào xíng， wéi yī wèn tí shì lù chéng huì duō liǎng gōng lǐ， shāo wēi yuǎn yì diǎn。','Cũng có một con đường nhỏ trong khu dân cư đi vòng được, chỉ có điều xa hơn khoảng hai cây số thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','阮明',6,'没关系的，多绕一点路完全没问题，只要别耽误上课就好，麻烦您绕路啦！','méi guān xì de， duō rào yì diǎn lù wán quán méi wèn tí， zhǐ yào bié dān wù shàng kè jiù hǎo， má fán nín rào lù la！','Không sao đâu ạ, đi vòng xa thêm chút cũng được, miễn đừng trễ học là được, phiền bác đi đường vòng giúp em nhé!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_07','V236','司机',7,'绕行小路里面行人、电动车多，车速提不上来，最多只能匀速慢慢开。','rào xíng xiǎo lù lǐ miàn xíng rén、 diàn dòng chē duō， chē sù tí bù shàng lái， zuì duō zhǐ néng yún sù màn màn kāi。','Đường nhỏ đi vòng này nhiều người đi bộ với xe điện lắm, không chạy nhanh được đâu, chỉ đi từ từ đều đều thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_08','V236','阮明',8,'我能理解，安全第一，只要能避开主干道的长堵车我就很满足。','wǒ néng lǐ jiě， ān quán dì yī， zhǐ yào néng bì kāi zhǔ gàn dào de zhǎng dǔ chē wǒ jiù hěn mǎn zú。','Em hiểu mà, an toàn là trên hết, chỉ cần tránh được cảnh tắc đường dài trên đường lớn là em mãn nguyện rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_09','V236','司机',9,'没问题，我现在立刻变道下高架，转入旁边的支路绕行。','méi wèn tí， wǒ xiàn zài lì kè biàn dào xià gāo jià， zhuǎn rù páng biān de zhī lù rào xíng。','Được rồi, tôi đổi làn xuống cầu vượt ngay bây giờ, rẽ vào đường nhánh bên cạnh để đi vòng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_10','V236','阮明',10,'大概还需要几分钟能抵达学校校门，我心里好有个数。','dà gài hái xū yào jǐ fēn zhōng néng dǐ dá xué xiào xiào mén， wǒ xīn lǐ hǎo yǒu gè shù。','Khoảng mấy phút nữa thì tới cổng trường ạ, để em biết mà yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_11','V236','司机',11,'顺利的话七八分钟就能到，比原地干等快二十分钟不止。','shùn lì de huà qī bā fēn zhōng jiù néng dào， bǐ yuán dì gàn děng kuài èr shí fēn zhōng bù zhǐ。','Thuận lợi thì bảy tám phút là tới, còn nhanh hơn đứng chôn chân chờ tới hai mươi phút ấy chứ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_12','V236','阮明',12,'太好了，这下不用担心迟到被扣平时分，辛苦您特意绕路！','tài hǎo le， zhè xià bù yòng dān xīn chí dào bèi kòu píng shí fēn， xīn kǔ nín tè yì rào lù！','Tuyệt quá, vậy là khỏi lo bị trễ học rồi bị trừ điểm chuyên cần, cảm ơn bác đã cất công đi vòng giúp em!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_13','V236','司机',13,'小事一桩，学生上课要紧，我尽量平稳开车不耽误你。','xiǎo shì yī zhuāng， xué shēng shàng kè yào jǐn， wǒ jǐn liàng píng wěn kāi chē bù dān wù nǐ。','Chuyện nhỏ thôi, học sinh đi học mới quan trọng, tôi sẽ cố lái êm để không làm chậm trễ em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_14','V236','阮明',14,'等下车我给您五星好评，真的太感谢您了！','děng xià chē wǒ gěi nín wǔ xīng hǎo píng， zhēn de tài gǎn xiè nín le！','Lát xuống xe em cho bác năm sao luôn, thật sự cảm ơn bác nhiều lắm!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng ba mươi tám tệ, phiền anh/chị thanh toán giúp em nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Vâng, em trả tiền mặt được không ạ? Em không mang điện thoại để quét mã.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi anh/chị nhé, cửa hàng em giờ không nhận tiền mặt nữa, chỉ nhận quét mã WeChat hoặc Alipay thôi ạ.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Ra vậy à, vậy để em mở điện thoại quét mã ngay đây.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, anh/chị cứ từ từ thao tác, thanh toán xong em xuất hóa đơn liền.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Thanh toán xong rồi nè, cảm ơn đã nhắc em nhé!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Cô ơi, máy giặt bỏ xu ở phòng giặt bị hỏng rồi, bỏ tiền vào mà không thấy phản ứng gì cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt à? Để cô ra xem thử nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Dạ đúng ạ, con thử hai lần rồi vẫn không được, quần áo bỏ vào mà không giặt nổi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này đang bị trục trặc tạm thời, con đổi qua dùng cái máy bên cạnh là được nhé.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Dạ vâng, vậy máy hỏng chừng nào mới sửa xong ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai thợ tới kiểm tra sửa, tối nay con cứ dùng tạm máy khác nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô rồi, cảm ơn cô nhiều ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Chào chị, xin lỗi vì đã làm phiền chị ạ! Hình như em đi nhầm chiều tàu điện ngầm rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu, đừng lo, em định đi đâu vậy?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đi khu đô thị đại học, vừa nãy lên tàu bị ngược chiều rồi, giờ không biết đổi chuyến thế nào ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ở ga tiếp theo, sang sân ga đối diện bắt tuyến số hai là đi thẳng tới nơi luôn nhé.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Dạ vâng, vậy em không cần mua vé lại đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi chuyến trong ga là miễn phí hết, em cứ yên tâm lên tàu nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Cảm ơn chị nhiều lắm ạ, chị giúp em một việc lớn thật đó!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì đâu, lần sau nhìn kỹ chiều rồi hãy lên tàu nhé.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào bạn, bạn là Nguyễn Minh phải không? Hàng thu hộ của bạn tới rồi nè, là chăn ga với đồ bếp đúng không?','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi, phiền bạn kiểm tra lại thông tin giúp mình nha! Số điện thoại đuôi 3621 đúng không?','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng rồi đó! Địa chỉ cũng là ký túc xá lưu học sinh của trường. Cước phí tổng cộng là 28 tệ nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ơ? Mình thấy trên app dự tính là 22 tệ, sao lại dư ra 6 tệ vậy?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của bạn nặng quá cân đó, phần vượt cân phải bù thêm cước phí, app dự tính không chính xác đâu.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy, thế thì không sao, mình quét mã trả tiền nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được rồi! Trả xong mình ký nhận cho bạn, đồ đạc còn nguyên vẹn hết, bạn có thể kiểm tra thử.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu, cảm ơn bạn đã vất vả chạy một chuyến nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Em ơi, hôm nay muốn ăn gì nào? Cơm hay mì?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Dạ cô ơi, cho con một phần cơm trứng chiên cà chua, cảm ơn cô!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được rồi! Có muốn thêm món kèm không? Rau xanh với khoai tây đều tươi hết.','AM08');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Dạ thôi ạ! Phiền cô nhất định đừng cho cay nha, con không ăn được cay chút nào luôn.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Cô nhớ rồi, cô làm cho con vị thanh đạm.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, cảm ơn cô nha!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ thôi mà! Sắp xong rồi, con đợi xíu nhé.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Anh Vũ ơi, mấy hôm nay em thấy hơi khó chịu, muốn nói với anh một chuyện.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Nhìn sắc mặt em không được tốt lắm, khó ở à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là do chưa quen thủy thổ, tối cứ ngủ không ngon, ban ngày lên lớp thì buồn ngủ kinh khủng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay thấy em ít nói hẳn! Vậy em định tính sao đây?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em định chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Dĩ nhiên là được rồi! Em cứ nghỉ ngơi cho khỏe, tối anh nói nhỏ lại, không làm phiền em đâu.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự phiền anh quá!','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì chứ, bạn cùng phòng vốn phải chăm sóc lẫn nhau mà.','AM09');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Chào cô Vương, làm phiền cô rồi ạ! Em muốn hỏi thăm về quy định khách vào trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào em, có bạn định đến ký túc tìm em à?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng rồi, mai bạn em muốn đến ký túc tìm em, cần đăng ký thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy tối có thể vào thăm không ạ? Em định hẹn gặp nhau vào buổi tối.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Tối thì không được đâu, ký túc xá khóa cửa lúc mười giờ, buổi tối cấm người ngoài vào trường.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Ra là vậy, thế thì em đổi sang ban ngày vậy, cảm ơn cô đã cho em biết ạ!','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không sao đâu, sắp xếp trước là được rồi, nhớ nhắc bạn em mang giấy tờ tùy thân nha.','AM06');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','提前主动告知行程变动，中国人一般不会严厉追责，但短期房屋预留存在时间限制，过夜空置房东有权收取空置费用；诚恳沟通大多可以免除额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','阮明',1,'刘哥您好，不好意思打扰您休息，有件事需要跟您协商调整。','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín xiū xī， yǒu jiàn shì xū yào gēn nín xié shāng diào zhěng。','Chào anh Lưu, xin lỗi vì đã làm phiền anh nghỉ ngơi, có việc này em cần trao đổi với anh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','房东',2,'你好同学，我记得咱们约定好今天下午两点过来办理房屋入住的对吧？','nǐ hǎo tóng xué， wǒ jì de zán men yuē dìng hǎo jīn tiān xià wǔ liǎng diǎn guò lái bàn lǐ fáng wū rù zhù de duì ba？','Chào em, anh nhớ là hai bên đã hẹn hai giờ chiều nay đến làm thủ tục nhận phòng đúng không?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','阮明',3,'非常抱歉！我乘坐的入境航班大面积延误，落地时间推迟六个小时，今天肯定赶不过来了呢。','fēi cháng bào qiàn！ wǒ chéng zuò de rù jìng háng bān dà miàn jī yán wù， luò dì shí jiān tuī chí liù gè xiǎo shí， jīn tiān kěn dìng gǎn bù guò lái le ne。','Em thật sự xin lỗi ạ! Chuyến bay nhập cảnh em đi bị hoãn trên diện rộng, giờ hạ cánh bị lùi lại sáu tiếng, hôm nay chắc chắn em không kịp đến rồi ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','房东',4,'这样啊？我今天专门空出一下午在家等你交接，临时变动确实有点麻烦。','zhè yàng a？ wǒ jīn tiān zhuān mén kòng chū yī xià wǔ zài jiā děng nǐ jiāo jiē， lín shí biàn dòng què shí yǒu diǎn má fán。','Vậy à? Hôm nay anh đã dành hẳn buổi chiều ở nhà đợi bàn giao nhà cho em, thay đổi đột xuất thế này đúng là hơi phiền đấy.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','阮明',5,'我特别理解您的不便，机场工作人员说最快明天下午两点才能抵达市区。','wǒ tè bié lǐ jiě nín de bù biàn， jī chǎng gōng zuò rén yuán shuō zuì kuài míng tiān xià wǔ liǎng diǎn cái néng dǐ dá shì qū。','Em rất hiểu sự bất tiện của anh, nhân viên sân bay nói sớm nhất cũng phải chiều mai hai giờ em mới tới được trung tâm thành phố.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','房东',6,'我原本计划今天交接完房屋，晚上出门办事，现在行程全部打乱了。','wǒ yuán běn jì huà jīn tiān jiāo jiē wán fáng wū， wǎn shàng chū mén bàn shì， xiàn zài háng chéng quán bù dǎ luàn le。','Anh vốn định hôm nay bàn giao nhà xong là tối ra ngoài giải quyết việc, giờ lịch trình bị đảo lộn hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','阮明',7,'能不能麻烦您帮我延后一天入住，明天下午我准时到，绝不再次迟到？','néng bù néng má fán nín bāng wǒ yán hòu yī tiān rù zhù， míng tiān xià wǔ wǒ zhǔn shí dào， jué bù zài cì chí dào？','Anh có thể giúp em lùi lại một ngày nhận phòng được không ạ, chiều mai em sẽ đến đúng giờ, tuyệt đối không trễ nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','房东',8,'按理当天预留的房间只能保留至当日深夜，过夜预留需要额外收取半天空置费。','àn lǐ dàng tiān yù liú de fáng jiān zhǐ néng bǎo liú zhì dāng rì shēn yè， guò yè yù liú xū yào é wài shōu qǔ bàn tiān kōng zhì fèi。','Theo quy định thì phòng giữ trong ngày chỉ được bảo lưu đến khuya hôm đó thôi, muốn giữ qua đêm thì phải trả thêm phí bỏ trống nửa ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_09','V244','阮明',9,'我明白规则，只要能保留房间，相关费用我可以正常承担。','wǒ míng bái guī zé， zhǐ yào néng bǎo liú fáng jiān， xiāng guān fèi yòng wǒ kě yǐ zhèng cháng chéng dān。','Em hiểu quy định mà, miễn là giữ được phòng thì phần phí đó em sẵn sàng đóng bình thường ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_10','V244','房东',10,'看你是留学生刚来国内不容易，空置费我就不收了，但今天房间不再单独为你预留。','kàn nǐ shì liú xué shēng gāng lái guó nèi bù róng yì， kōng zhì fèi wǒ jiù bù shōu le， dàn jīn tiān fáng jiān bù zài dān dú wèi nǐ yù liú。','Thấy em là du học sinh mới sang, cũng không dễ dàng gì, phí bỏ trống thì anh không thu, nhưng hôm nay anh sẽ không giữ riêng phòng cho em nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_11','V244','阮明',11,'太感谢您的理解和体谅，临时行程变动给您添了不少麻烦，真的不好意思！','tài gǎn xiè nín de lǐ jiě hé tǐ liàng， lín shí xíng chéng biàn dòng gěi nín tiān le bù shǎo má fán， zhēn de bù hǎo yì sī！','Em cảm ơn anh rất nhiều vì đã thông cảm và thấu hiểu, việc thay đổi lịch trình đột xuất này gây phiền cho anh nhiều quá, thật sự xin lỗi ạ!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_12','V244','房东',12,'不用客气，出门在外难免有突发变动嘛，但是明天抵达前一小时一定要提前跟我说一声。','bù yòng kè qì， chū mén zài wài nán miǎn yǒu tū fā biàn dòng ma， dàn shì míng tiān dǐ dá qián yī xiǎo shí yí dìng yào tí qián gēn wǒ shuō yī shēng。','Không cần khách sáo đâu, đi xa khó tránh khỏi có chuyện phát sinh mà, nhưng trước khi đến một tiếng ngày mai nhớ nhắn tin báo anh trước nha.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_13','V244','阮明',13,'我一定提前发消息告知您到站时间，方便您提前到家等候。','wǒ yí dìng tí qián fā xiāo xī gào zhī nín dào zhàn shí jiān， fāng biàn nín tí qián dào jiā děng hòu。','Em nhất định sẽ nhắn tin báo anh giờ em đến trước, để anh tiện về nhà đợi sẵn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_14','V244','房东',14,'好，那我们就约定明天下午两点办理入住，明天见！','hǎo， nà wǒ men jiù yuē dìng míng tiān xià wǔ liǎng diǎn bàn lǐ rù zhù， míng tiān jiàn！','Được, vậy mình hẹn hai giờ chiều mai làm thủ tục nhận phòng nhé, hẹn gặp mai!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này giá bao nhiêu một thùng vậy ạ?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 tệ một thùng, mấy hôm nay bên chị đang có chương trình khuyến mãi đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy khuyến mãi gì vậy chị, có lời không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng giảm thẳng 20 tệ, khá lời đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, thế thì em mua hai thùng luôn, bình thường em uống nhiều mà.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được rồi, để chị quét mã cho em, lúc thanh toán sẽ tự động trừ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ được, cảm ơn chị!','AM08');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Cô ơi, cho con hỏi rau củ quả cân ở đây đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi con, con đặt đồ lên rồi chọn đúng tên rau là được.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ ghê, con bấm mấy lần rồi mà sao không ra tem vậy cô?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để cô xem nào, con chọn là cải thảo mà đồ con cầm là rau xanh, chọn nhầm loại rồi kìa.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Ra là vậy, thảo nào cứ không được, để con làm lại.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, cứ từ từ, dán tem xong là ra máy tự thanh toán được rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Con cảm ơn cô nhiều lắm, không thì con phải loay hoay lâu lắm luôn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货；生鲜食品变质优先全额退款，避免顾客再次购买同类问题产品。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我有一件商品存在质量问题，想来售后窗口处理退换。','nǐ hǎo， wǒ yǒu yī jiàn shāng pǐn cún zài zhì liàng wèn tí， xiǎng lái shòu hòu chuāng kǒu chǔ lǐ tuì huàn。','Chào anh, em có một món hàng bị lỗi chất lượng, muốn đến quầy hậu mãi để đổi trả ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦先跟我说一下是什么商品，什么时候在店内购买的？','nín hǎo， má fán xiān gēn wǒ shuō yī xià shì shén me shāng pǐn， shén me shí hòu zài diàn nèi gòu mǎi de？','Chào em, phiền em nói giúp anh đây là món hàng gì, mua ở cửa hàng lúc nào vậy?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'是一款全麦吐司面包，昨天傍晚在生鲜烘焙区选购的，今天早上拆开就发霉了。','shì yī kuǎn quán mài tǔ sī miàn bāo， zuó tiān bàng wǎn zài shēng xiān hōng bèi qū xuǎn gòu de， jīn tiān zǎo shàng chāi kāi jiù fā méi le。','Dạ là một ổ bánh mì nguyên cám, em mua chiều tối hôm qua ở khu thực phẩm tươi sống với bánh nướng, sáng nay bóc ra thì đã bị mốc rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'麻烦出示一下对应的购物小票，我们需要核对购买时间和批次信息。','má fán chū shì yī xià duì yìng de gòu wù xiǎo piào， wǒ men xū yào hé duì gòu mǎi shí jiān hé pī cì xìn xī。','Phiền em cho anh xem hóa đơn mua hàng tương ứng, bên anh cần đối chiếu thời gian mua và thông tin lô hàng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'小票我一直妥善收在钱包里，现在拿给您，我全程常温存放，根本没放多久呀。','xiǎo piào wǒ yì zhí tuǒ shàn shōu zài qián bāo lǐ， xiàn zài ná gěi nín， wǒ quán chéng cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Hóa đơn em vẫn cất cẩn thận trong ví, đây em đưa anh, em bảo quản ở nhiệt độ thường suốt, có để lâu đâu ạ.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'我对照系统入库记录核对面包批次，确认是商品本身出厂保鲜出现问题，非常抱歉哈。','wǒ duì zhào xì tǒng rù kù jì lù hé duì miàn bāo pī cì， què rèn shì shāng pǐn běn shēn chū chǎng bǎo xiān chū xiàn wèn tí， fēi cháng bào qiàn hā。','Anh đối chiếu với hồ sơ nhập kho trên hệ thống rồi, xác nhận đúng là do sản phẩm xuất xưởng có vấn đề bảo quản, thật xin lỗi em nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'没关系，我也不是故意为难店里，只是担心同类商品其他顾客买到。','méi guān xì， wǒ yě bú shì gù yì wéi nán diàn lǐ， zhǐ shì dān xīn tóng lèi shāng pǐn qí tā gù kè mǎi dào。','Không sao đâu ạ, em cũng không cố ý làm khó cửa hàng, chỉ lo khách khác lỡ mua phải sản phẩm cùng loại thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_08','V303','店员',8,'您愿意换新商品，还是直接申请全额退款，两种方案都可以执行。','nín yuàn yì huàn xīn shāng pǐn， hái shì zhí jiē shēn qǐng quán é tuì kuǎn， liǎng zhǒng fāng àn dōu kě yǐ zhí xíng。','Em muốn đổi sản phẩm mới, hay là làm thủ tục hoàn tiền toàn bộ luôn, cả hai phương án đều được hết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_09','V303','阮明',9,'这款面包我不敢再选购同款，直接办理全额退款会更合适。','zhè kuǎn miàn bāo wǒ bù gǎn zài xuǎn gòu tóng kuǎn， zhí jiē bàn lǐ quán é tuì kuǎn huì gèng hé shì。','Loại bánh này em không dám chọn lại nữa, làm thủ tục hoàn tiền toàn bộ luôn sẽ hợp lý hơn ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_10','V303','店员',10,'没问题，我现在操作后台退款，资金会原路返还到您付款的支付软件。','méi wèn tí， wǒ xiàn zài cāo zuò hòu tái tuì kuǎn， zī jīn huì yuán lù fǎn huán dào nín fù kuǎn de zhī fù ruǎn jiàn。','Không vấn đề gì, anh thao tác hoàn tiền trên hệ thống ngay đây, tiền sẽ hoàn về đúng phần mềm thanh toán em đã dùng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_11','V303','阮明',11,'退款到账大概需要多长时间，会不会有延迟？','tuì kuǎn dào zhàng dà gài xū yào duō zhǎng shí jiān， huì bú huì yǒu yán chí？','Vậy tiền hoàn về mất khoảng bao lâu ạ, có bị chậm trễ gì không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_12','V303','店员',12,'线上支付退款实时到账，您现在打开手机就能查到余额变动。','xiàn shàng zhī fù tuì kuǎn shí shí dào zhàng， nín xiàn zài dǎ kāi shǒu jī jiù néng chá dào yú é biàn dòng。','Hoàn tiền thanh toán online là về ngay lập tức, em mở điện thoại lên là thấy số dư thay đổi liền.',NULL);
